{
  "name": "Timepix/SPIDR像素探测器采集系统",
  "name_en": "Timepix/SPIDR Pixel Detector Acquisition System",
  "manufacturer": "",
  "description": "用于连接SPIDR并初始化、控制一个或多个Timepix像素探测器的采集系统，可设置偏置电压、启动或停止采集、通过轮询或回调接收数据，并将采集数据记录到文件。",
  "description_en": "An acquisition system for connecting to SPIDR and initializing and controlling one or more Timepix pixel detectors. It supports bias voltage control, starting and stopping acquisition, receiving data by polling or callback, and recording acquired data to files.",
  "actions": [
    {
      "action_name": "auto-data_thread",
      "description": "运行数据接收线程。",
      "description_en": "Run the data reception thread."
    },
    {
      "action_name": "auto-biasVoltage",
      "description": "获取或设置偏置电压。",
      "description_en": "Get or set the bias voltage."
    },
    {
      "action_name": "auto-poll",
      "description": "轮询读取缓冲区中的采集数据。",
      "description_en": "Poll acquired data from the buffer."
    },
    {
      "action_name": "auto-pollBufferLength",
      "description": "获取或设置轮询缓冲区长度。",
      "description_en": "Get or set the polling buffer length."
    },
    {
      "action_name": "auto-dataCallback",
      "description": "获取或设置数据接收回调函数。",
      "description_en": "Get or set the data-received callback function."
    },
    {
      "action_name": "auto-enablePolling",
      "description": "启用轮询模式。",
      "description_en": "Enable polling mode."
    },
    {
      "action_name": "auto-start_recording",
      "description": "开始将采集数据记录到指定路径。",
      "description_en": "Start recording acquired data to the specified path."
    },
    {
      "action_name": "auto-stop_recording",
      "description": "停止记录采集数据。",
      "description_en": "Stop recording acquired data."
    },
    {
      "action_name": "auto-start",
      "description": "开始采集。",
      "description_en": "Start acquisition."
    },
    {
      "action_name": "auto-stop",
      "description": "停止采集。",
      "description_en": "Stop acquisition."
    },
    {
      "action_name": "auto-isAcquiring",
      "description": "获取是否正在采集。",
      "description_en": "Get whether acquisition is active."
    },
    {
      "action_name": "auto-numDevices",
      "description": "获取已连接设备数量。",
      "description_en": "Get the number of connected devices."
    },
    {
      "action_name": "auto-chanAddress",
      "description": "获取或设置通道地址。",
      "description_en": "Get or set the channel address."
    },
    {
      "action_name": "auto-getDevice",
      "description": "获取指定编号的Timepix设备对象。",
      "description_en": "Get the Timepix device object for a specified index."
    }
  ],
  "tag_hints": [
    "Timepix detector",
    "SPIDR readout",
    "pixel detector acquisition",
    "bias voltage control",
    "event data polling",
    "detector data recording"
  ]
}

